from datetime import datetime, timezone
from decimal import Decimal
from ledgerly.models import Payment
from ledgerly.support import process_refund_request
from ledgerly.errors import BillingError
T0=datetime(2026,1,1,tzinfo=timezone.utc)
def p(status="captured"): return Payment("pay","inv",Decimal("100.00"),status=status,created_at=T0,captured_at=T0)
# rounding
x=p(); process_refund_request(x,"49.999","u",T0); print("round",x.refunded_amount)
# partial then full
x=p(); process_refund_request(x,"40","u",T0); print(x.status,x.refunded_amount)
process_refund_request(x,"60.00","u",T0); print(x.status,x.refunded_amount)
# over
x=p()
try: process_refund_request(x,"100.01","u",T0)
except BillingError as e: print("over",e.code)
# non-positive
for a in ["0","-1"]:
    try: process_refund_request(p(),a,"u",T0)
    except BillingError as e: print("bad",a,e.code)
# not captured
try: process_refund_request(p("authorized"),"1","u",T0)
except BillingError as e: print("state",e.code)
EOF"}

